fn read(p:&str)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert!(!Path::new(&format!("{R}/inputs.json")).exists());assert_eq!(hash(FIELD),"1200e63547baa41c299a48e3221f1cef85990b0369f17452dc12eb17045f9713");let m=read(&format!("{Z}/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json"));let mut pins=BTreeMap::new();for(p,h)in m["source_files_sha256"].as_object().unwrap(){let p=format!("{Z}/{p}");assert_eq!(hash(&p),h.as_str().unwrap());pins.insert(p,h.as_str().unwrap().to_string());}
 let fixture_map="/home/ubuntu/src/zopro-perf-work/query-wrapper176/fixtures.json";let fixtures=read(fixture_map);pins.insert(fixture_map.to_string(),hash(fixture_map));for v in fixtures.as_object().unwrap().values(){for k in["fixture","oracle"]{let p=v[k].as_str().unwrap();pins.insert(p.to_string(),hash(p));}assert_eq!(hash(v["fixture"].as_str().unwrap()),v["fixture_sha256"].as_str().unwrap());}
 let case_map="/home/ubuntu/src/zopro-perf-work/coarse-proof-phase-universal176/cases.json";pins.insert(case_map.to_string(),hash(case_map));let mut images=BTreeMap::new();for s in["1x2","2x2"]{let cases=read(case_map);let c=cases.as_array().unwrap().iter().find(|v|v["shape"]==s).unwrap();let image=c["image"].as_str().unwrap();let digest=hash(image);assert_eq!(digest,c["image_sha256"]);pins.insert(image.to_string(),digest.clone());images.insert(s.to_string(),json!({"image":image,"image_sha256":digest}));}
 let prior=format!("{Z}/docs/benchmarks/2026-10-24-point-io-component/evidence/keypoint-census-result.json");pins.insert(prior.clone(),hash(&prior));let inputs=json!({"images":images,"fixtures":fixtures,"prior_exact_primary_census":prior,"field_library":FIELD,"field_library_sha256":hash(FIELD),"source_manifest":format!("{Z}/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json"),"no_new_core_linked":true});fs::write(format!("{R}/inputs.json"),serde_json::to_vec_pretty(&inputs).unwrap()).unwrap();
 let serde=format!("{DEPS}/libserde_json-cdebb9338c2784ad.rlib");let sha=format!("{DEPS}/libsha2-16b8f2c03bdf5faa.rlib");for p in[FIELD,RUSTC,&serde,&sha]{pins.insert(p.to_string(),hash(p));}for file in["prepare.rs","design.md","codec.rs","census.rs","inputs.json"]{let p=format!("{R}/{file}");pins.insert(p.clone(),hash(&p));}
 let compile=|tests:bool|{let mut v=vec![RUSTC.to_string(),"--edition=2021".into(),"-O".into(),"-C".into(),"target-cpu=native".into(),"-C".into(),"lto=fat".into(),"-C".into(),"codegen-units=1".into(),format!("{R}/census.rs"),"-L".into(),format!("dependency={DEPS}"),"--extern".into(),format!("zopro_bn254={FIELD}"),"--extern".into(),format!("serde_json={serde}"),"--extern".into(),format!("sha2={sha}")];if tests{v.push("--test".into());}v.extend(["-o".into(),format!("{R}/{}",if tests{"census-tests"}else{"census"})]);v};
 let step=|name:&str,args:Vec<String>|json!({"kind":"command","name":name,"argv":args,"timeout_seconds":1200});let steps=vec![step("compile-tests",compile(true)),step("orbit-and-group-tests",vec![format!("{R}/census-tests"),"--test-threads=1".into()]),step("compile-census",compile(false)),step("census",vec![format!("{R}/census")])];
 fs::write(format!("{R}/pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(format!("{R}/plan.json"),serde_json::to_vec_pretty(&json!({"version":1,"source_pins":format!("{R}/pins.json"),"steps":steps})).unwrap()).unwrap();println!("Prepared14view census, three focused tests, four fixed commands, {}input/source pins; production unchanged.",pins.len());}
